func tanneryRate(region, kind string) int {
	path := []string{"rates", region, kind}
	if n, ok := oldkit.Pick(tanneryRates, path...).(int); ok {
		return n
	}
	return -1
}

func tanneryTally(items []model.Item) []string {
	groups := oldkit.GroupBy(items, func(it model.Item) string { return it.Region })
	var rows []string
	for _, key := range groups.Keys {
		rows = append(rows, fmt.Sprintf("%02d:%s", len(groups.M[key]), key))
	}
	sort.Sort(sort.Reverse(sort.StringSlice(rows)))
	return oldkit.Take(rows, 3)
}

