// Package oldkit is the helper package this codebase has used so far.  It is being retired: see README.md.
package oldkit

import (
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"shop/model"
)

var logLines []string

var qtyRe = regexp.MustCompile(`^\s*([0-9]+)\s*([A-Za-z]*)\s*$`)

// FmtAmount gives "12.50 GBP" style text for an integer number of cents; the currency defaults to "GBP".
func FmtAmount(cents int, cur ...string) string {
	c := "GBP"
	if len(cur) > 0 {
		c = cur[0]
	}
	sign := ""
	if cents < 0 {
		sign = "-"
		cents = -cents
	}
	return fmt.Sprintf("%s%d.%02d %s", sign, cents/100, cents%100, c)
}

// ParseQty reads "12 kg", "3x" or "7" (the unit defaults to "ea"); ok is false when the text is not a quantity.
func ParseQty(text string) (count int, unit string, ok bool) {
	m := qtyRe.FindStringSubmatch(text)
	if m == nil {
		return 0, "", false
	}
	n, err := strconv.Atoi(m[1])
	if err != nil {
		return 0, "", false
	}
	u := m[2]
	if u == "" {
		u = "ea"
	}
	return n, u, true
}

// PadRight pads on the right: the text stays at the left.
func PadRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

// PadLeft pads on the left: the text moves to the right.
func PadLeft(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return strings.Repeat(" ", width-len(s)) + s
}

// Title capitalises words.
func Title(s string) string {
	words := strings.Fields(s)
	for i, w := range words {
		if i > 0 {
			words[i] = strings.ToLower(w)
		}
	}
	t := strings.Join(words, " ")
	if t == "" {
		return ""
	}
	return strings.ToUpper(t[:1]) + strings.ToLower(t[1:])
}

// CompareNames orders names case-insensitively, then by the exact text.
func CompareNames(a, b string) int {
	x, y := strings.ToLower(a), strings.ToLower(b)
	if x != y {
		if x < y {
			return -1
		}
		return 1
	}
	return strings.Compare(a, b)
}

// Pick looks up a nested map[string]any by keys; nil when a key is missing.
func Pick(m map[string]any, keys ...string) any {
	var cur any = m
	for _, k := range keys {
		next, ok := cur.(map[string]any)
		if !ok {
			return nil
		}
		cur, ok = next[k]
		if !ok {
			return nil
		}
	}
	return cur
}

// Take returns at most the first n strings.
func Take(xs []string, n int) []string {
	if n > len(xs) {
		n = len(xs)
	}
	return append([]string(nil), xs[:n]...)
}

// Groups is the result of GroupBy: the keys in order of first appearance and the items of each key.
type Groups struct {
	Keys []string
	M    map[string][]model.Item
}

// GroupBy buckets items by key.
func GroupBy(items []model.Item, key func(model.Item) string) Groups {
	g := Groups{M: map[string][]model.Item{}}
	for _, it := range items {
		k := key(it)
		if _, seen := g.M[k]; !seen {
			g.Keys = append(g.Keys, k)
		}
		g.M[k] = append(g.M[k], it)
	}
	return g
}

// Log appends "<LEVEL> msg key=value ..." (keys sorted) to the global log and returns the line; kv is key, value, key, value...
func Log(level, msg string, kv ...any) string {
	ctx := map[string]string{}
	var keys []string
	for i := 0; i+1 < len(kv); i += 2 {
		k := fmt.Sprint(kv[i])
		ctx[k] = fmt.Sprint(kv[i+1])
		keys = append(keys, k)
	}
	sort.Strings(keys)
	line := "<" + strings.ToUpper(level) + "> " + msg
	for _, k := range keys {
		line += " " + k + "=" + ctx[k]
	}
	logLines = append(logLines, line)
	return line
}

// FlushLog returns the global log and clears it.
func FlushLog() []string {
	out := logLines
	logLines = nil
	return out
}

// Clamp limits x to lo..hi.
func Clamp(x, lo, hi int) int {
	if x < lo {
		return lo
	}
	if x > hi {
		return hi
	}
	return x
}

