// Demo module cooperage of the shop application.
package main

import (
	"fmt"

	"shop/kit"
)

var cooperageFactors = map[string]int{"box": 10, "m": 11, "l": 7}

func cooperageQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return 0
	}
	factor, found := cooperageFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

func cooperageLine(name string, qty, cents int) string {
	return kit.Pad(name, 10, kit.AlignLeft) + kit.Pad(kit.Money{Cents: qty * cents, Cur: "USD"}.Text(), 9, kit.AlignRight)
}

func cooperageNote(oid string, n int) int {
	kit.Default().Emit("info", "sold out", kit.F{"order": oid, "count": n})
	return n * 5
}

var cooperageRates = map[string]any{"rates": map[string]any{"hills": map[string]any{"spare": 61, "bulk": 90, "fresh": 5}, "east": map[string]any{"spare": 52, "dried": 82, "loose": 26}, "west": map[string]any{"bulk": 29, "fresh": 65, "sealed": 84}}}

func cooperageRate(region, kind string) int {
	if n, ok := kit.Dig(cooperageRates, []string{"rates", region, kind}, nil).(int); ok {
		return n
	}
	return -1
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageQty(\"26 box\")", cooperageQty("26 box")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageQty(\"7x\")", cooperageQty("7x")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageQty(\"11\")", cooperageQty("11")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageQty(\"lots of it\")", cooperageQty("lots of it")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageQty(\"\")", cooperageQty("")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageQty(\" 2 L \")", cooperageQty(" 2 L ")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageLine(\"barrel\", 6, 75)", cooperageLine("barrel", 6, 75)))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageLine(\"needle (large)\", 34, 2)", cooperageLine("needle (large)", 34, 2)))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageNote(\"A60\", 20)", cooperageNote("A60", 20)))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageNote(\"B48\", 27)", cooperageNote("B48", 27)))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageRate(\"hills\", \"spare\")", cooperageRate("hills", "spare")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageRate(\"east\", \"sealed\")", cooperageRate("east", "sealed")))
	out = append(out, fmt.Sprintf("%s = %#v", "cooperageRate(\"atlantis\", \"spare\")", cooperageRate("atlantis", "spare")))
	out = append(out, kit.Default().Drain()...)
	return out
}

func main() {
	for _, line := range demo() {
		fmt.Println(line)
	}
}

