// Demo module creamery of the shop application.
package main

import (
	"fmt"
	"strings"

	"shop/kit"
)

func creameryNote(oid string, n int) string {
	events := kit.Default()
	events.Emit("warn", "moved", kit.F{"order": oid, "left": n - 5})
	return strings.ToUpper(events.Last())
}

func creameryCapped(deltas []int) int {
	acc := 0
	for _, x := range deltas {
		acc = kit.Limit(acc+x, -10, 40)
	}
	return acc
}

var creameryFactors = map[string]int{"g": 9, "pc": 6, "kg": 9}

func creameryQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return 0
	}
	factor, found := creameryFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

var creameryHeader = kit.Pad("NAME", 10, kit.AlignLeft) + kit.Pad("TOTAL", 8, kit.AlignRight)

func creameryHeaderLine() string {
	return creameryHeader + "|"
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "creameryNote(\"A83\", 11)", creameryNote("A83", 11)))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryNote(\"B14\", 8)", creameryNote("B14", 8)))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryCapped([]int{26, -6, 31, -28, -24, -10})", creameryCapped([]int{26, -6, 31, -28, -24, -10})))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryQty(\"15 kg\")", creameryQty("15 kg")))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryQty(\"5x\")", creameryQty("5x")))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryQty(\"10\")", creameryQty("10")))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryQty(\"lots of it\")", creameryQty("lots of it")))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryQty(\"\")", creameryQty("")))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryQty(\" 5 L \")", creameryQty(" 5 L ")))
	out = append(out, fmt.Sprintf("%s = %#v", "creameryHeaderLine()", creameryHeaderLine()))
	out = append(out, kit.Default().Drain()...)
	return out
}

func main() {
	for _, line := range demo() {
		fmt.Println(line)
	}
