)

func workshopCapped(deltas []int) int {
	acc := 0
	for _, x := range deltas {
		acc = kit.Limit(acc+x, 0, 50)
	}
	return acc
}

func workshopQty(text string) bool {
	_, err := kit.ParseQty(text)
	return err == nil
}

var workshopHeader = kit.Pad("NAME", 10, kit.AlignLeft) + kit.Pad("TOTAL", 10, kit.AlignRight)

func workshopHeaderLine() string {
	return workshopHeader + "|"
}

func workshopTally(items []model.Item) (int, []string, int) {
	groups := kit.GroupBy(items, func(it model.Item) string { return it.Kind })
	biggest := 0
	var keys []string
	for _, g := range groups {
		keys = append(keys, g.Key)
		if len(g.Items) > biggest {
			biggest = len(g.Items)
		}
	}
	return len(groups), keys, biggest
}

var workshopRates = map[string]any{"rates": map[string]any{"east": map[string]any{"sealed": 10, "loose": 4, "bulk": 79}, "south": map[string]any{"dried": 84, "sealed": 29, "spare": 28}, "north": map[string]any{"loose": 87, "bulk": 77, "fresh": 28}}}

func workshopRate(region, kind string) int {
	byKind, _ := kit.Dig(workshopRates, []string{"rates", region}, nil).(map[string]any)
	n, ok := byKind[kind].(int)
	if !ok {
		n = 5
	}
	if extra, ok := kit.Dig(workshopRates, []string{"rates", "nowhere"}, nil).(int); ok {
		n += extra
	}
	return n
}

func demo() []string {
	var out []string
