func fisheryPadded(texts []string) []string {
	right := func(t string) string { return common.PadLeft(t, 10) }
	left := func(t string) string { return common.PadRight(t, 10) }
	var out []string
	for _, t := range texts {
		out = append(out, right(t)+"|"+left(t))
	}
	return out
}

func fisheryTally(items []model.Item) (int, []string, int) {
	groups := common.GroupBy(items, func(it model.Item) string { return it.Kind })
	biggest := 0
	for _, members := range groups.M {
