package kit

import "fmt"

// Money is an amount in cents of a currency; both fields matter.
type Money struct {
	Cents int
	Cur   string
}

// Text gives "12.50 EUR" style text.
func (m Money) Text() string {
	cents, sign := m.Cents, ""
	if cents < 0 {
		sign = "-"
		cents = -cents
	}
	return fmt.Sprintf("%s%d.%02d %s", sign, cents/100, cents%100, m.Cur)
}

