// Demo module bakery of the shop application.
package main

import (
	"fmt"
	"sort"
	"strings"

	"shop/kit"
	"shop/model"
)

func bakeryTally(items []model.Item) []string {
	sizes := map[string]int{}
	var keys []string
	for _, g := range kit.GroupBy(items, func(it model.Item) string { return it.Kind }) {
		sizes[g.Key] = len(g.Items)
		keys = append(keys, g.Key)
	}
	sort.Strings(keys)
	var out []string
	for _, key := range keys {
		out = append(out, fmt.Sprintf("%s=%d", key, sizes[key]))
	}
	return kit.First(out, 2)
}

var bakeryHeader = kit.Pad("NAME", 10, kit.AlignLeft) + kit.Pad("TOTAL", 10, kit.AlignRight)

func bakeryHeaderLine() string {
	return bakeryHeader + "|"
}

func bakeryNote(oid string, n int) string {
	events := kit.Default()
	events.Emit("warn", "moved", kit.F{"order": oid, "left": n - 3})
	return strings.ToUpper(events.Last())
}

var bakeryFactors = map[string]int{"g": 5, "kg": 6, "box": 3}

func bakeryQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return 1
	}
	factor, found := bakeryFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryTally(rows)", bakeryTally([]model.Item{{Kind: "spare", Region: "east", Unit: "kg"}, {Kind: "dried", Region: "south", Unit: "kg"}, {Kind: "dried", Region: "east", Unit: "l"}, {Kind: "fresh", Region: "south", Unit: "l"}, {Kind: "spare", Region: "east", Unit: "pc"}})))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryHeaderLine()", bakeryHeaderLine()))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryNote(\"A10\", 11)", bakeryNote("A10", 11)))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryNote(\"B73\", 15)", bakeryNote("B73", 15)))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryQty(\"28 kg\")", bakeryQty("28 kg")))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryQty(\"1x\")", bakeryQty("1x")))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryQty(\"9\")", bakeryQty("9")))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryQty(\"lots of it\")", bakeryQty("lots of it")))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryQty(\"\")", bakeryQty("")))
	out = append(out, fmt.Sprintf("%s = %#v", "bakeryQty(\" 4 L \")", bakeryQty(" 4 L ")))
	out = append(out, kit.Default().Drain()...)
