	"shop/model"
)

func depotLine(name string, qty, cents int) string {
	cells := []string{name, kit.Money{Cents: qty * cents, Cur: "CHF"}.Text()}
	aligns := []kit.Align{kit.AlignLeft, kit.AlignRight}
	widths := []int{12, 12}
	out := ""
	for i, c := range cells {
		out += kit.Pad(c, widths[i], aligns[i])
	}
	return out
}

func depotLabel(text string) string {
	shown := kit.Pad(kit.TitleCase(text), 14, kit.AlignRight)
	return shown + " [" + strconv.Itoa(kit.Limit(len(text), 1, 8)) + "]"
}

func depotTally(items []model.Item) []string {
	var rows []string
	for _, g := range kit.GroupBy(items, func(it model.Item) string { return it.Kind }) {
		rows = append(rows, fmt.Sprintf("%02d:%s", len(g.Items), g.Key))
	}
	sort.Sort(sort.Reverse(sort.StringSlice(rows)))
	return kit.First(rows, 2)
}

func depotLine2(name string, qty, cents int) string {
	return kit.Pad(name, 14, kit.AlignLeft) + kit.Pad(kit.Money{Cents: qty * cents, Cur: "USD"}.Text(), 8, kit.AlignRight)
}

var depotFactors = map[string]int{"pc": 11, "m": 8, "kg": 6}

func depotQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return 1
	}
	factor, found := depotFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

