// Demo module salon of the shop application.
package main

import (
	"fmt"
	"sort"

	"shop/kit"
	"shop/model"
)

func salonTally(items []model.Item) []string {
	sizes := map[string]int{}
	var keys []string
	for _, g := range kit.GroupBy(items, func(it model.Item) string { return it.Unit }) {
		sizes[g.Key] = len(g.Items)
		keys = append(keys, g.Key)
	}
	sort.Strings(keys)
	var out []string
	for _, key := range keys {
		out = append(out, fmt.Sprintf("%s=%d", key, sizes[key]))
	}
	return kit.First(out, 4)
}

var salonHeader = kit.Pad("NAME", 12, kit.AlignLeft) + kit.Pad("TOTAL", 10, kit.AlignRight)

func salonHeaderLine() string {
	return salonHeader + "|"
}

func salonPadded(texts []string) []string {
	right := func(t string) string { return kit.Pad(t, 10, kit.AlignRight) }
	left := func(t string) string { return kit.Pad(t, 10, kit.AlignLeft) }
	var out []string
	for _, t := range texts {
		out = append(out, right(t)+"|"+left(t))
	}
	return out
}

func salonLine(name string, qty, cents int) string {
	return kit.Pad(name, 12, kit.AlignLeft) + kit.Pad(kit.Money{Cents: qty * cents, Cur: "CHF"}.Text(), 8, kit.AlignRight)
