	out = append(out, fmt.Sprintf("%s = %#v", "salonTally(rows)", salonTally([]model.Item{{Kind: "fresh", Region: "east", Unit: "kg"}, {Kind: "dried", Region: "north", Unit: "kg"}, {Kind: "fresh", Region: "north", Unit: "pc"}, {Kind: "dried", Region: "north", Unit: "pc"}, {Kind: "fresh", Region: "east", Unit: "l"}, {Kind: "dried", Region: "east", Unit: "pc"}})))
