func atelierPadded(texts []string) []string {
	right := func(t string) string { return kit.Pad(t, 8, kit.AlignRight) }
	left := func(t string) string { return kit.Pad(t, 8, kit.AlignLeft) }
	var out []string
	for _, t := range texts {
		out = append(out, right(t)+"|"+left(t))
	}
	return out
}

var atelierHeader = kit.Pad("NAME", 10, kit.AlignLeft) + kit.Pad("TOTAL", 8, kit.AlignRight)

func atelierHeaderLine() string {
	return atelierHeader + "|"
}

var atelierFactors = map[string]int{"l": 3, "kg": 8, "m": 6}

func atelierQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return 1
	}
	factor, found := atelierFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

func atelierLine(name string, qty, cents int) string {
	return kit.Pad(name, 12, kit.AlignLeft) + kit.Pad(kit.Money{Cents: qty * cents, Cur: "USD"}.Text(), 10, kit.AlignRight)
}

func atelierTally(items []model.Item) []string {
	var rows []string
	for _, g := range kit.GroupBy(items, func(it model.Item) string { return it.Region }) {
		rows = append(rows, fmt.Sprintf("%02d:%s", len(g.Items), g.Key))
	}
	sort.Sort(sort.Reverse(sort.StringSlice(rows)))
	return kit.First(rows, 3)
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "atelierPadded([]string{\"needle\", \"lamp\", \"scroll\"})", atelierPadded([]string{"needle", "lamp", "scroll"})))
