	out = append(out, fmt.Sprintf("%s = %#v", "atelierLine(\"scroll\", 5, 1250)", atelierLine("scroll", 5, 1250)))
	out = append(out, fmt.Sprintf("%s = %#v", "atelierLine(\"needle (large)\", 28, 333)", atelierLine("needle (large)", 28, 333)))
	out = append(out, fmt.Sprintf("%s = %#v", "atelierTally(rows)", atelierTally([]model.Item{{Kind: "fresh", Region: "south", Unit: "pc"}, {Kind: "spare", Region: "east", Unit: "kg"}, {Kind: "dried", Region: "east", Unit: "l"}, {Kind: "fresh", Region: "east", Unit: "kg"}, {Kind: "dried", Region: "north", Unit: "l"}, {Kind: "spare", Region: "north", Unit: "kg"}, {Kind: "dried", Region: "east", Unit: "pc"}, {Kind: "spare", Region: "north", Unit: "l"}})))
	return out
}

func main() {
	for _, line := range demo() {
		fmt.Println(line)
	}
