func bakeryTally(items []model.Item) (int, []string, int) {
	groups := kit.GroupBy(items, func(it model.Item) string { return it.Kind })
	biggest := 0
	var keys []string
	for _, g := range groups {
		keys = append(keys, g.Key)
		if len(g.Items) > biggest {
			biggest = len(g.Items)
		}
	}
	return len(groups), keys, biggest
}

var bakeryRates = map[string]any{"rates": map[string]any{"west": map[string]any{"dried": 25, "bulk": 14, "fresh": 47}, "coast": map[string]any{"sealed": 43, "fresh": 27, "dried": 15}, "north": map[string]any{"spare": 32, "bulk": 9, "fresh": 85}}}

func bakeryRate(region, kind string) int {
	if n, ok := kit.Dig(bakeryRates, []string{"rates", region, kind}, nil).(int); ok {
		return n
	}
	return -1
}

var bakeryFactors = map[string]int{"g": 2, "m": 3, "box": 12}

func bakeryQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return -1
	}
	factor, found := bakeryFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

