var atelierHeader = oldkit.PadRight("NAME", 10) + oldkit.PadLeft("TOTAL", 8)

func atelierHeaderLine() string {
	return atelierHeader + "|"
}

var atelierFactors = map[string]int{"l": 3, "kg": 8, "m": 6}

func atelierQty(text string) int {
	count, unit, ok := oldkit.ParseQty(text)
	if !ok {
		return 1
	}
	factor, found := atelierFactors[unit]
	if !found {
		factor = 1
	}
	return count * factor
}

func atelierLine(name string, qty, cents int) string {
