CASES = os.path.join(ROOT, "tests", "examples.json")
BUILD = ""
RUN = [(ROOT + "/" + p[2:]) if p.startswith("@/") else p for p in ["go", "-C", "@/", "run"]]
TIMEOUT = 30
WORKERS = 3


def build():
    if not BUILD:
        return True
    r = subprocess.run(["bash", "-c", BUILD], cwd=ROOT, capture_output=True, text=True)
    if r.returncode != 0:
        print("BUILD FAILED")
        print((r.stdout + r.stderr)[-3000:])
        return False
    return True


def execute(c):
