	aligns := []kit.Align{kit.AlignLeft, kit.AlignRight}
	widths := []int{14, 8}
	out := ""
	for i, c := range cells {
		out += kit.Pad(c, widths[i], aligns[i])
	}
	return out
}

var garageRates = map[string]any{"rates": map[string]any{"west": map[string]any{"bulk": 89, "sealed": 62, "dried": 86}, "coast": map[string]any{"spare": 13, "dried": 18, "fresh": 58}, "east": map[string]any{"dried": 84, "sealed": 70, "bulk": 37}}}

func garageRate(region, kind string) int {
	byKind, _ := kit.Dig(garageRates, []string{"rates", region}, nil).(map[string]any)
	n, ok := byKind[kind].(int)
	if !ok {
		n = 5
	}
	if extra, ok := kit.Dig(garageRates, []string{"rates", "nowhere"}, nil).(int); ok {
		n += extra
	}
	return n
}

func garageLine2(name string, qty, cents int) string {
	cells := []string{name, kit.Money{Cents: qty * cents, Cur: "GBP"}.Text()}
	aligns := []kit.Align{kit.AlignLeft, kit.AlignRight}
	widths := []int{12, 9}
	out := ""
	for i, c := range cells {
		out += kit.Pad(c, widths[i], aligns[i])
	}
	return out
}

func garageTally(items []model.Item) (int, []string, int) {
	groups := kit.GroupBy(items, func(it model.Item) string { return it.Unit })
	biggest := 0
	var keys []string
	for _, g := range groups {
		keys = append(keys, g.Key)
		if len(g.Items) > biggest {
			biggest = len(g.Items)
		}
	}
	return len(groups), keys, biggest
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "garageNote(\"A48\", 3)", garageNote("A48", 3)))
	out = append(out, fmt.Sprintf("%s = %#v", "garageNote(\"B43\", 16)", garageNote("B43", 16)))
