	out = append(out, fmt.Sprintf("%s = %#v", "garageRate(\"west\", \"bulk\")", garageRate("west", "bulk")))
	out = append(out, fmt.Sprintf("%s = %#v", "garageRate(\"coast\", \"dried\")", garageRate("coast", "dried")))
	out = append(out, fmt.Sprintf("%s = %#v", "garageRate(\"atlantis\", \"bulk\")", garageRate("atlantis", "bulk")))
	out = append(out, fmt.Sprintf("%s = %#v", "garageLine2(\"jar\", 2, 9990)", garageLine2("jar", 2, 9990)))
	out = append(out, fmt.Sprintf("%s = %#v", "garageLine2(\"scroll (large)\", 13, -75)", garageLine2("scroll (large)", 13, -75)))
	out = append(out, fmt.Sprintf("%s = %#v", "garageTally(rows)", func() []any { a, b, c := garageTally([]model.Item{{Kind: "spare", Region: "north", Unit: "pc"}, {Kind: "fresh", Region: "north", Unit: "l"}, {Kind: "dried", Region: "south", Unit: "l"}, {Kind: "dried", Region: "south", Unit: "kg"}, {Kind: "dried", Region: "north", Unit: "kg"}}); return []any{a, b, c} }()))
	out = append(out, kit.Default().Drain()...)
	return out
}

