// Demo module apiary of the shop application.
package main

import (
	"fmt"
	"sort"

	"shop/kit"
	"shop/model"
)

func apiaryTally(items []model.Item) []string {
	sizes := map[string]int{}
	var keys []string
	for _, g := range kit.GroupBy(items, func(it model.Item) string { return it.Kind }) {
		sizes[g.Key] = len(g.Items)
		keys = append(keys, g.Key)
	}
	sort.Strings(keys)
	var out []string
	for _, key := range keys {
		out = append(out, fmt.Sprintf("%s=%d", key, sizes[key]))
	}
	return kit.First(out, 3)
}

var apiaryRates = map[string]any{"rates": map[string]any{"south": map[string]any{"fresh": 3, "bulk": 23, "dried": 79}, "coast": map[string]any{"bulk": 80, "spare": 44, "loose": 3}, "north": map[string]any{"sealed": 30, "loose": 14, "dried": 13}}}

func apiaryRate(region, kind string) int {
	path := []string{"rates", region, kind}
	if n, ok := kit.Dig(apiaryRates, path, nil).(int); ok {
		return n
	}
	return 5
}

var apiaryFactors = map[string]int{"box": 11, "kg": 3, "g": 6}

func apiaryQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return 0
	}
	factor, found := apiaryFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

func apiaryEvent(msg string, ctx kit.F) string {
	events := kit.Default()
	events.Emit("debug", msg, ctx)
	return events.Last()
}

func apiaryNote(oid string, n int) int {
	apiaryEvent("moved", kit.F{"order": oid, "n": n})
	return n + 2
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryTally(rows)", apiaryTally([]model.Item{{Kind: "spare", Region: "north", Unit: "l"}, {Kind: "dried", Region: "north", Unit: "kg"}, {Kind: "spare", Region: "north", Unit: "kg"}, {Kind: "spare", Region: "north", Unit: "pc"}, {Kind: "spare", Region: "east", Unit: "kg"}, {Kind: "dried", Region: "north", Unit: "l"}, {Kind: "spare", Region: "south", Unit: "pc"}, {Kind: "dried", Region: "north", Unit: "kg"}})))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryRate(\"south\", \"fresh\")", apiaryRate("south", "fresh")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryRate(\"coast\", \"fresh\")", apiaryRate("coast", "fresh")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryRate(\"atlantis\", \"fresh\")", apiaryRate("atlantis", "fresh")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"13 box\")", apiaryQty("13 box")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"3x\")", apiaryQty("3x")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"19\")", apiaryQty("19")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"lots of it\")", apiaryQty("lots of it")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"\")", apiaryQty("")))
