	widths := []int{14, 12}
	out := ""
	for i, c := range cells {
		out += kit.Pad(c, widths[i], aligns[i])
	}
	return out
}

func chandleryPadded(texts []string) []string {
	right := func(t string) string { return kit.Pad(t, 10, kit.AlignRight) }
	left := func(t string) string { return kit.Pad(t, 10, kit.AlignLeft) }
	var out []string
	for _, t := range texts {
		out = append(out, right(t)+"|"+left(t))
	}
	return out
}

var chandleryRates = map[string]any{"rates": map[string]any{"south": map[string]any{"spare": 37, "bulk": 52, "dried": 56}, "hills": map[string]any{"sealed": 77, "fresh": 47, "bulk": 61}, "coast": map[string]any{"dried": 19, "loose": 23, "spare": 63}}}

func chandleryRate(region, kind string) int {
	byKind, _ := kit.Dig(chandleryRates, []string{"rates", region}, nil).(map[string]any)
	n, ok := byKind[kind].(int)
	if !ok {
		n = 0
	}
	if extra, ok := kit.Dig(chandleryRates, []string{"rates", "nowhere"}, nil).(int); ok {
		n += extra
	}
	return n
}

func chandleryCapped(deltas []int) int {
	acc := 0
	for _, x := range deltas {
		acc = kit.Limit(acc+x, 5, 100)
	}
	return acc
}

