	q, err := kit.ParseQty(text)
	if err != nil {
		return -1
	}
	factor, found := hatcheryFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

var hatcheryFactors2 = map[string]int{"box": 2, "l": 4, "kg": 5}

