	out := make([]string, len(xs))
	for i, x := range xs {
		out[i] = fn(x)
	}
	return out
}

func stableLabels(names []string) []string {
	return stableMapAll(names, kit.TitleCase)
}

var stableRates = map[string]any{"rates": map[string]any{"hills": map[string]any{"fresh": 45, "bulk": 63, "dried": 18}, "south": map[string]any{"bulk": 55, "loose": 28, "fresh": 38}, "north": map[string]any{"bulk": 56, "dried": 56, "loose": 39}}}

func stableRate(region, kind string) int {
	if n, ok := kit.Dig(stableRates, []string{"rates", region, kind}, nil).(int); ok {
		return n
	}
	return 0
}

func stableQty(text string) string {
	if q, err := kit.ParseQty(text); err == nil {
		return q.Unit
	}
	return "none"
}

func stableTally(items []model.Item) (int, []string, int) {
	groups := kit.GroupBy(items, func(it model.Item) string { return it.Unit })
	biggest := 0
	var keys []string
	for _, g := range groups {
		keys = append(keys, g.Key)
