func apiaryTally(items []model.Item) []string {
	groups := legacy.GroupBy(items, func(it model.Item) string { return it.Kind })
	keys := append([]string(nil), groups.Keys...)
	sort.Strings(keys)
	var out []string
	for _, key := range keys {
