// Demo module apiary of the shop application.
package main

import (
	"fmt"
	"sort"

	"shop/kit"
	"shop/model"
)

func apiaryTally(items []model.Item) []string {
	var rows []string
	for _, g := range kit.GroupBy(items, func(it model.Item) string { return it.Unit }) {
		rows = append(rows, fmt.Sprintf("%02d:%s", len(g.Items), g.Key))
	}
	sort.Sort(sort.Reverse(sort.StringSlice(rows)))
	return kit.First(rows, 4)
}

var apiaryHeader = kit.Pad("NAME", 10, kit.AlignLeft) + kit.Pad("TOTAL", 8, kit.AlignRight)

func apiaryHeaderLine() string {
	return apiaryHeader + "|"
}

func apiaryLine(name string, qty, cents int) string {
	return kit.Pad(name, 10, kit.AlignLeft) + kit.Pad(kit.Money{Cents: qty * cents, Cur: "GBP"}.Text(), 8, kit.AlignRight)
}

func apiaryNote(oid string, n int) int {
	kit.Default().Emit("info", "moved", kit.F{"order": oid, "count": n})
	return n * 7
}

var apiaryFactors = map[string]int{"pc": 5, "l": 5, "box": 4}

func apiaryQty(text string) int {
	q, err := kit.ParseQty(text)
	if err != nil {
		return 0
	}
	factor, found := apiaryFactors[q.Unit]
	if !found {
		factor = 1
	}
	return q.Count * factor
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryTally(rows)", apiaryTally([]model.Item{{Kind: "fresh", Region: "north", Unit: "kg"}, {Kind: "spare", Region: "east", Unit: "l"}, {Kind: "fresh", Region: "south", Unit: "kg"}, {Kind: "fresh", Region: "east", Unit: "kg"}, {Kind: "spare", Region: "south", Unit: "kg"}, {Kind: "fresh", Region: "north", Unit: "kg"}})))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryHeaderLine()", apiaryHeaderLine()))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryLine(\"badge\", 2, 100)", apiaryLine("badge", 2, 100)))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryLine(\"ticket (large)\", 48, 2)", apiaryLine("ticket (large)", 48, 2)))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryNote(\"A55\", 5)", apiaryNote("A55", 5)))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryNote(\"B72\", 16)", apiaryNote("B72", 16)))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"12 l\")", apiaryQty("12 l")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"5x\")", apiaryQty("5x")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"16\")", apiaryQty("16")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"lots of it\")", apiaryQty("lots of it")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\"\")", apiaryQty("")))
	out = append(out, fmt.Sprintf("%s = %#v", "apiaryQty(\" 6 L \")", apiaryQty(" 6 L ")))
	out = append(out, kit.Default().Drain()...)
	return out
}

func main() {
	for _, line := range demo() {
		fmt.Println(line)
	}
}

