func breweryLine(name string, qty, cents int) string {
	cells := []string{name, kit.Money{Cents: qty * cents, Cur: "GBP"}.Text()}
	aligns := []kit.Align{kit.AlignLeft, kit.AlignRight}
	widths := []int{14, 8}
	out := ""
	for i, c := range cells {
		out += kit.Pad(c, widths[i], aligns[i])
	}
	return out
}

var breweryRates = map[string]any{"rates": map[string]any{"west": map[string]any{"dried": 8, "sealed": 27, "bulk": 83}, "coast": map[string]any{"spare": 71, "loose": 28, "fresh": 29}, "south": map[string]any{"spare": 7, "fresh": 2, "dried": 56}}}

func breweryRate(region, kind string) int {
	byKind, _ := kit.Dig(breweryRates, []string{"rates", region}, nil).(map[string]any)
	n, ok := byKind[kind].(int)
	if !ok {
		n = 0
	}
	if extra, ok := kit.Dig(breweryRates, []string{"rates", "nowhere"}, nil).(int); ok {
		n += extra
	}
	return n
}

var breweryHeader = kit.Pad("NAME", 12, kit.AlignLeft) + kit.Pad("TOTAL", 10, kit.AlignRight)

func breweryHeaderLine() string {
	return breweryHeader + "|"
}

func breweryTally(items []model.Item) []string {
	sizes := map[string]int{}
	var keys []string
	for _, g := range kit.GroupBy(items, func(it model.Item) string { return it.Region }) {
		sizes[g.Key] = len(g.Items)
		keys = append(keys, g.Key)
	}
	sort.Strings(keys)
	var out []string
	for _, key := range keys {
		out = append(out, fmt.Sprintf("%s=%d", key, sizes[key]))
	}
	return kit.First(out, 2)
}

func demo() []string {
	var out []string
	out = append(out, fmt.Sprintf("%s = %#v", "breweryLabels([]string{\"iron gate\", \"amber copper\", \"old harbour\", \"  spaced   out  words \"})", breweryLabels([]string{"iron gate", "amber copper", "old harbour", "  spaced   out  words "})))
