	out = append(out, fmt.Sprintf("%s = %#v", "breweryTally(rows)", breweryTally([]model.Item{{Kind: "fresh", Region: "south", Unit: "kg"}, {Kind: "dried", Region: "north", Unit: "pc"}, {Kind: "spare", Region: "south", Unit: "l"}, {Kind: "dried", Region: "east", Unit: "kg"}, {Kind: "fresh", Region: "east", Unit: "l"}, {Kind: "fresh", Region: "east", Unit: "pc"}, {Kind: "spare", Region: "south", Unit: "l"}, {Kind: "dried", Region: "south", Unit: "kg"}})))
	return out
