var garageRates = map[string]any{"rates": map[string]any{"east": map[string]any{"dried": 37, "bulk": 23, "sealed": 86}, "north": map[string]any{"dried": 3, "fresh": 39, "sealed": 9}, "hills": map[string]any{"fresh": 77, "loose": 90, "bulk": 76}}}

