	if n, ok := oldkit.Pick(garageRates, path...).(int); ok {
		return n
	}
	return 5
}

func garageTally(items []model.Item) (int, []string, int) {
	groups := oldkit.GroupBy(items, func(it model.Item) string { return it.Unit })
	biggest := 0
	for _, members := range groups.M {
		if len(members) > biggest {
			biggest = len(members)
		}
	}
	return len(groups.M), groups.Keys, biggest
}

